import{_ as r,C as d,o,c as n,a5 as i,b as l,w as t,a as h,E as s,a6 as D,j as p}from"./chunks/framework.BEZBAInb.js";const N=JSON.parse('{"title":"대화 데이터","description":"","frontmatter":{"title":"대화 데이터","order":1},"headers":[],"relativePath":"ko/2.4/tutorial/core/shot-and-dialogue.md","filePath":"ko/2.4/tutorial/core/shot-and-dialogue.md","lastUpdated":1788455378000}'),_={name:"ko/2.4/tutorial/core/shot-and-dialogue.md"};function c(K,a,u,E,B,S){const e=d("Mermaid");return o(),n("div",null,[a[1]||(a[1]=i('<h1 id="knd-shot-및-knd-dialogue" tabindex="-1">KND_Shot 및 KND_Dialogue <a class="header-anchor" href="#knd-shot-및-knd-dialogue" aria-label="Permalink to &quot;KND_Shot 및 KND_Dialogue&quot;">​</a></h1><h2 id="머리말" tabindex="-1">머리말 <a class="header-anchor" href="#머리말" aria-label="Permalink to &quot;머리말&quot;">​</a></h2><p>이 장에서는 Konado의 두 핵심 클래스인 KND_Shot과 KND_Dialogue를 소개합니다. 이 두 클래스는 Konado의 핵심이며 대화 샷과 대화를 나타내는 데 사용됩니다. Konado의 아키텍처 원리를 깊이 이해하려면 이 두 클래스를 이해하는 것이 매우 중요합니다. 충분히 이해한 뒤에는 필요에 따라 확장하고 수정할 수 있습니다.</p><h2 id="knd-shot" tabindex="-1">KND_Shot <a class="header-anchor" href="#knd-shot" aria-label="Permalink to &quot;KND_Shot&quot;">​</a></h2><h3 id="정의" tabindex="-1">정의 <a class="header-anchor" href="#정의" aria-label="Permalink to &quot;정의&quot;">​</a></h3><p>KND_Shot은 하나의 대화 샷을 나타내는 Konado의 핵심 클래스입니다.</p><p>샷은 영상과 애니메이션 제작의 기본 개념으로, 보통 여러 프레임으로 이루어진 연속 화면을 의미합니다. 여기서 KND_Shot 클래스는 일련의 대화를 포함한 대화 샷을 나타냅니다.</p><p>책의 개념으로 이해할 수도 있습니다. 하나의 샷은 작은 장이고, 대화 샷은 그 작은 장 안의 대화입니다.</p><p>KND_Shot은 흩어져 있는 KND_Dialogue 데이터 객체를 조직하고 일정한 순서로 배열하여, 재생 시 지정된 순서대로 재생될 수 있게 합니다.</p><p>다만 영화의 샷과 달리 KND_Shot은 반드시 연속적이고 선형적인 이야기를 의미하지 않습니다. 여러 branch 분기로 구성될 수 있으며, 각 분기는 일련의 대화를 포함하고 choice와 조합되어 다중 선택 분기를 구현해 사용자가 서로 다른 대화 경로를 선택할 수 있게 합니다.</p><h3 id="knd-shot과-konadoscript의-관계" tabindex="-1">KND_Shot과 KonadoScript의 관계 <a class="header-anchor" href="#knd-shot과-konadoscript의-관계" aria-label="Permalink to &quot;KND_Shot과 KonadoScript의 관계&quot;">​</a></h3><p>사용하다 보면 기본적으로 KND_Shot을 수동으로 만들 필요가 없다는 점을 알 수 있습니다. KND_Shot은 KonadoScript가 자동으로 만들고 데이터를 자동으로 업데이트합니다. 이는 사용자 지정 KonadoScript 문법과 KonadoScript 파서를 사용해 스크립트 파일을 파싱하고, 원본 파일의 각 줄을 KND_Dialogue 객체로 변환한 다음 일정한 규칙에 따라 KND_Shot 객체로 조직하기 때문입니다.</p><p>흐름도로 표현하면 KonadoScript에서 여러 KND_Dialogue를 거쳐 KND_Shot으로 가는 과정은 대략 다음과 같습니다.</p>',13)),(o(),l(D,null,{default:t(()=>[s(e,{id:"mermaid-39",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%22KonadoScript%20%EC%9B%90%EB%B3%B8%20%ED%8C%8C%EC%9D%BC%22%5D%20--%3E%20B%5B%22%ED%8C%8C%EC%84%9C%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22KND_Dialogue%20%EA%B0%9D%EC%B2%B4%20%EC%83%9D%EC%84%B1%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%EA%B7%9C%EC%B9%99%EC%97%90%20%EB%94%B0%EB%9D%BC%20%EC%A1%B0%EC%A7%81%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22KND_Shot%20%EC%9E%90%EB%8F%99%20%EC%83%9D%EC%84%B1%2F%EC%97%85%EB%8D%B0%EC%9D%B4%ED%8A%B8%22%5D%0A%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=p("p",null,"KonadoScript의 파싱 과정을 자세히 알고 싶다면 KonadoScript 관련 문서와 파서 소스 코드를 참고하세요.",-1))])}const k=r(_,[["render",c]]);export{N as __pageData,k as default};
